//! gipfel-core: headless port of the gipfel computational core.
//!
//! Modules:
//! - [`hill`]: hill database (CSV load, duplicate marking)
//! - [`panorama`]: viewpoint, geodesy, refraction, occlusion, visibility
//! - [`projection`]: rectilinear/cylindrical projections with symbolic
//!   derivatives generated by maxima (see `codegen/`)
//! - [`lsq`]: Levenberg-Marquardt fit of the view parameters (system GSL)
//! - [`metadata`]: `gipfel:` JPEG comment + EXIF read/write

pub mod hill;
pub mod lsq;
pub mod metadata;
pub mod panorama;
pub mod profile;
pub mod projection;
pub mod stitch;
pub mod track;

pub use hill::Hill;
pub use metadata::ImageMetaData;
pub use panorama::Panorama;
pub use projection::{Projection, ProjectionType, ViewParams};
